/* @lc app=leetcode id=1499 lang=kotlin */ class Solution { fun findMaxValueOfEquation(points: Array<IntArray>, k: Int): Int = points.indices.fold(ArrayDeque<Int>() to Int.MIN_VALUE) { (dq, maxVal), j -> points[j].let { (xj, yj) -> generateSequence { dq.firstOrNull()?.takeIf { xj - points[it][0] > k }?.also { dq.removeFirst() } }.count().let { (dq.firstOrNull()?.let { maxOf(maxVal, points[it][1] - points[it][0] + yj + xj) } ?: maxVal).let { newMax -> generateSequence { dq.lastOrNull()?.takeIf { points[it][1] - points[it][0] <= yj - xj }?.also { dq.removeLast() } }.count().let { dq.also { it.addLast(j) } to newMax } } } } }.second }